#include <stdio.h>
    #include <stdlib.h>
    #include <string.h>
    #include <errno.h>
    #include <unistd.h>
    #include <sys/types.h>
    #include <sys/wait.h>
    #include <sys/sysinfo.h>
    #include <sys/stat.h>
    #include <fcntl.h>
    #include <pthread.h>
    #include <signal.h>
    #include <time.h>

    #define MAX_PROCESSES 1024
    #define MAX_ARGS 16
    #define MAX_CMD_LEN 256

    typedef struct {
        int pid;
        int ppid;
        int pgid;
        int sid;
        char state;
        char tty[32];
        char cmd[MAX_CMD_LEN];
    } process_info_t;

    process_info_t processes[MAX_PROCESSES];
    int num_processes = 0;

    void get_process_info() {
        FILE *fp;
        char buf[256];
        char state;
        int pid, ppid, pgid, sid;
        char tty[32];
        char cmd[MAX_CMD_LEN];
        int i = 0;

        fp = fopen("/proc/self/stat", "r");
        if (fp == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }

        while (fgets(buf, sizeof(buf), fp) != NULL) {
            if (sscanf(buf, "%d %s %c %d %d %d %s %s", &pid, tty, &state, &ppid, &pgid, &sid, cmd, MAX_CMD_LEN) != 8) {
                fprintf(stderr, "Invalid process information\n");
                exit(EXIT_FAILURE);
            }
            processes[i].pid = pid;
            processes[i].ppid = ppid;
            processes[i].pgid = pgid;
            processes[i].sid = sid;
            processes[i].state = state;
            strncpy(processes[i].tty, tty, sizeof(tty));
            strncpy(processes[i].cmd, cmd, sizeof(cmd));
            i++;
        }
        fclose(fp);
        num_processes = i;
    }

    void print_processes() {
        int i;
        printf("PID\tPPID\tPGID\tSID\tSTATE\tTTY\tCMD\n");
        for (i = 0; i < num_processes; i++) {
            printf("%d\t%d\t%d\t%d\t%c\t%s\t%s\n", processes[i].pid, processes[i].ppid, processes[i].pgid, processes[i].sid, processes[i].state, processes[i].tty, processes[i].cmd);
        }
    }

    void print_usage() {
        printf("Usage: process_viewer [-h]\n");
        printf("  -h, --help    Show this help message\n");
    }

    int main(int argc, char **argv) {
        int i;
        int opt;
        int show_help = 0;

        while ((opt = getopt(argc, argv, "h")) != -1) {
            switch (opt) {
            case 'h':
                show_help = 1;
                break;
            default:
                printf("Unknown option: %c\n", opt);
                print_usage();
                exit(EXIT_FAILURE);
            }
        }

        if (show_help) {
            print_usage();
            exit(EXIT_SUCCESS);
        }

        get_process_info();
        print_processes();

        return 0;
    }

