// Program to create a scalable C System administration program
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <fcntl.h>
#include <errno.h>

// Define the port number and socket file descriptor
#define PORT 8080
int sock_fd;

// Function to create a socket
int create_socket() {
    // Create a socket
    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd == -1) {
        perror("Socket creation failed");
        exit(1);
    }
    return sock_fd;
}

// Function to bind the socket
int bind_socket() {
    // Bind the socket to the port
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);
    if (bind(sock_fd, (struct sockaddr *) &server_addr, sizeof(server_addr)) < 0) {
        perror("Socket binding failed");
        exit(1);
    }
    return sock_fd;
}

// Function to listen on the socket
int listen_socket() {
    // Listen for incoming connections
    if (listen(sock_fd, 3) < 0) {
        perror("Listen failed");
        exit(1);
    }
    return sock_fd;
}

// Function to accept an incoming connection
int accept_connection() {
    // Accept the incoming connection
    int new_sock_fd;
    struct sockaddr_in client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    new_sock_fd = accept(sock_fd, (struct sockaddr *) &client_addr, &client_addr_len);
    if (new_sock_fd < 0) {
        perror("Accept failed");
        exit(1);
    }
    return new_sock_fd;
}

// Function to handle the incoming connection
void handle_connection(int sock_fd) {
    // Read the incoming message
    char buffer[1024];
    int bytes_read = read(sock_fd, buffer, 1024);
    if (bytes_read < 0) {
        perror("Read failed");
        exit(1);
    }

    // Process the incoming message
    if (strncmp(buffer, "SHUTDOWN", 8) == 0) {
        // Shut down the system
        printf("Shutting down the system\n");
        system("shutdown -h now");
    } else {
        // Send a response
        char *response = "Invalid command";
        write(sock_fd, response, strlen(response));
    }
}

int main() {
    // Create a socket
    create_socket();

    // Bind the socket to the port
    bind_socket();

    // Listen on the socket
    listen_socket();

    // Accept incoming connections
    int new_sock_fd = accept_connection();

    // Handle the incoming connection
    handle_connection(new_sock_fd);

    // Close the socket
    close(sock_fd);
    return 0;
}

