// GPS Navigation Simulation
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

#define EARTH_RADIUS 6371000 // meters
#define PI 3.141592653589793

// Structures
typedef struct {
    double latitude;
    double longitude;
    double altitude;
} Position;

typedef struct {
    Position start;
    Position end;
    double distance;
    double time;
} Route;

// Functions
void initialize(Position* start, Position* end) {
    start->latitude = 45.521047;
    start->longitude = -73.586517;
    start->altitude = 0;

    end->latitude = 45.520612;
    end->longitude = -73.587019;
    end->altitude = 0;
}

double distance(Position* start, Position* end) {
    double dx = end->longitude - start->longitude;
    double dy = end->latitude - start->latitude;
    double dz = end->altitude - start->altitude;

    double distance = sqrt(dx*dx + dy*dy + dz*dz);

    return distance;
}

void simulate(Route* route) {
    // Initialize positions
    Position start;
    Position end;
    initialize(&start, &end);

    // Calculate distance and time
    route->distance = distance(&start, &end);
    route->time = route->distance / 1000; // 1000 meters per second

    // Print results
    printf("Distance: %.2f meters\n", route->distance);
    printf("Time: %.2f seconds\n", route->time);
}

int main() {
    Route route;
    simulate(&route);

    return 0;
}

