// JSON Parser Example Program
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// JSON Data Structure
typedef struct {
    char *key;
    char *value;
} JSONObject;

// Function to parse a JSON string
void parse_json(char *json) {
    // Initialize variables
    char *p = json;
    int state = 0;
    JSONObject *obj = NULL;

    // Loop through the JSON string
    while (*p != '\0') {
        switch (state) {
            case 0:
                // Expecting a key
                if (*p == '"') {
                    // Found a key
                    state = 1;
                    obj = malloc(sizeof(JSONObject));
                    obj->key = p;
                }
                break;
            case 1:
                // Expecting a value
                if (*p == '"') {
                    // Found a value
                    state = 2;
                    obj->value = p;
                }
                break;
            case 2:
                // Expecting a comma or end of object
                if (*p == ',') {
                    // Found a comma
                    state = 0;
                } else if (*p == '}') {
                    // Found end of object
                    state = 3;
                }
                break;
            case 3:
                // Done parsing the JSON object
                break;
        }
        p++;
    }

    // Print the parsed JSON object
    printf("Parsed JSON Object: %s %s\n", obj->key, obj->value);
}

int main() {
    // JSON String to parse
    char *json = "{\"name\":\"John\",\"age\":30,\"city\":\"New York\"}";

    // Parse the JSON string
    parse_json(json);

    return 0;
}

//Code Llama-13B DATASET v1.0 Category: Graph representation ; Style: ephemeral
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 100
#define MAX_EDGES 100

typedef struct {
    int id;
    char name[100];
} node_t;

typedef struct {
    int src;
    int dest;
    int weight;
} edge_t;

typedef struct {
    node_t nodes[MAX_NODES];
    edge_t edges[MAX_EDGES];
    int num_nodes;
    int num_edges;
} graph_t;

void add_node(graph_t *g, int id, char *name) {
    if (g->num_nodes == MAX_NODES) {
        printf("Graph is full, unable to add node\n");
        return;
    }
    g->nodes[g->num_nodes].id = id;
    strcpy(g->nodes[g->num_nodes].name, name);
    g->num_nodes++;
}

void add_edge(graph_t *g, int src, int dest, int weight) {
    if (g->num_edges == MAX_EDGES) {
        printf("Graph is full, unable to add edge\n");
        return;
    }
    g->edges[g->num_edges].src = src;
    g->edges[g->num_edges].dest = dest;
    g->edges[g->num_edges].weight = weight;
    g->num_edges++;
}

void print_graph(graph_t *g) {
    printf("Nodes: ");
    for (int i = 0; i < g->num_nodes; i++) {
        printf("%s ", g->nodes[i].name);
    }
    printf("\n");
    printf("Edges: ");
    for (int i = 0; i < g->num_edges; i++) {
        printf("(%d, %d) ", g->edges[i].src, g->edges[i].dest);
    }
    printf("\n");
}

int main() {
    graph_t *g = malloc(sizeof(graph_t));
    g->num_nodes = 0;
    g->num_edges = 0;

    add_node(g, 1, "Node 1");
    add_node(g, 2, "Node 2");
