// Greedy Algorithm example program in a complex style

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a job
struct Job {
    int id;
    int deadline;
    int profit;
};

// Function to sort jobs by deadline
int compare_jobs(const void* a, const void* b) {
    struct Job* job1 = (struct Job*)a;
    struct Job* job2 = (struct Job*)b;
    return job1->deadline - job2->deadline;
}

// Function to find the maximum profit
int find_max_profit(struct Job jobs[], int n) {
    // Sort jobs by deadline
    qsort(jobs, n, sizeof(struct Job), compare_jobs);

    // Initialize variables
    int max_profit = 0;
    int current_profit = 0;
    int current_time = 0;
    int i;

    // Iterate through jobs
    for (i = 0; i < n; i++) {
        // If the current job's deadline is less than or equal to the current time,
        // add its profit to the current profit and increment the current time by 1
        if (jobs[i].deadline <= current_time) {
            current_profit += jobs[i].profit;
            current_time++;
        }

        // If the current profit is greater than the maximum profit, update the maximum profit
        if (current_profit > max_profit) {
            max_profit = current_profit;
        }
    }

    return max_profit;
}

int main() {
    // Declare and initialize variables
    struct Job jobs[10] = {
        {1, 2, 50},
        {2, 1, 100},
        {3, 3, 150},
        {4, 4, 200},
        {5, 5, 300},
        {6, 6, 400},
        {7, 7, 500},
        {8, 8, 600},
        {9, 9, 700},
        {10, 10, 800}
    };
    int n = 10;

    // Find the maximum profit
    int max_profit = find_max_profit(jobs, n);

    // Print the maximum profit
    printf("The maximum profit is %d\n", max_profit);

    return 0;
}

