int cards[NUM_CARDS];
int num_cards = 0;
int num_matches = 0;

void init_cards() {
    for (int i = 0; i < NUM_CARDS; i++) {
        cards[i] = i + 1;
    }
}

void shuffle_cards() {
    srand(time(NULL));
    for (int i = 0; i < NUM_CARDS; i++) {
        int j = rand() % NUM_CARDS;
        int temp = cards[i];
        cards[i] = cards[j];
        cards[j] = temp;
    }
}

void print_cards() {
    for (int i = 0; i < NUM_CARDS; i++) {
        printf("%d ", cards[i]);
    }
    printf("\n");
}

