#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>

// Function to execute SQL query and print the results
void execute_query(sqlite3 *db, char *sql) {
    char *zErrMsg = 0;
    int rc;

    rc = sqlite3_exec(db, sql, NULL, 0, &zErrMsg);

    if (rc!= SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
    } else {
        fprintf(stdout, "Query executed successfully.\n");
    }
}

// Function to create a table in the database
void create_table(sqlite3 *db) {
    char *sql = "CREATE TABLE IF NOT EXISTS employees (" \
                "id INTEGER PRIMARY KEY AUTOINCREMENT," \
                "name TEXT NOT NULL," \
                "position TEXT NOT NULL," \
                "salary REAL NOT NULL);";

    execute_query(db, sql);
}

// Function to insert data into the table
void insert_data(sqlite3 *db) {
    char *sql = "INSERT INTO employees (name, position, salary) VALUES ('John Doe', 'Manager', 50000.00);";

    execute_query(db, sql);
}

// Function to update data in the table
void update_data(sqlite3 *db) {
    char *sql = "UPDATE employees SET salary = 60000.00 WHERE name = 'John Doe';";

    execute_query(db, sql);
}

// Function to delete data from the table
void delete_data(sqlite3 *db) {
    char *sql = "DELETE FROM employees WHERE name = 'John Doe';";

    execute_query(db, sql);
}

// Function to select data from the table
void select_data(sqlite3 *db) {
    char *sql = "SELECT * FROM employees;";

    execute_query(db, sql);
}

int main() {
    sqlite3 *db;
    int rc;

    // Open the database
    rc = sqlite3_open("test.db", &db);

    if (rc) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        return 1;
    }

    // Create a table
    create_table(db);

    // Insert data into the table
    insert_data(db);

    // Update data in the table
    update_data(db);

    // Delete data from the table
    delete_data(db);

    // Select data from the table
    select_data(db);

    // Close the database
    sqlite3_close(db);

    return 0;
}

