#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>

#define CPU_USAGE_INTERVAL 5 // in seconds

// Function to get CPU usage as a percentage
float get_cpu_usage() {
    FILE *fp;
    char filename[50] = "/proc/stat";
    float cpu_usage = 0;

    fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening file %s\n", filename);
        exit(1);
    }

    // Read the first line of the file
    char line[100];
    fgets(line, 100, fp);

    // Extract CPU usage information
    char *token = strtok(line, " ");
    while (token!= NULL) {
        if (strcmp(token, "cpu") == 0) {
            token = strtok(NULL, " ");
            int total_time = atoi(token);
            token = strtok(NULL, " ");
            int user_time = atoi(token);
            token = strtok(NULL, " ");
            int system_time = atoi(token);
            token = strtok(NULL, " ");
            int idle_time = atoi(token);

            // Calculate CPU usage as a percentage
            cpu_usage = ((float) (total_time - idle_time) / total_time) * 100;
            break;
        }
        token = strtok(NULL, " ");
    }

    fclose(fp);
    return cpu_usage;
}

// Function to print CPU usage
void print_cpu_usage(float cpu_usage) {
    printf("CPU usage: %.2f%%\n", cpu_usage);
}

// Main function
int main() {
    float cpu_usage = 0;
    while (1) {
        cpu_usage = get_cpu_usage();
        printf("CPU usage updated every %d seconds\n", CPU_USAGE_INTERVAL);
        print_cpu_usage(cpu_usage);
        sleep(CPU_USAGE_INTERVAL);
    }
    return 0;
}

