void init_deck(card deck[]){
    int i;
    for(i=0;i<52;i++){
        deck[i].rank=i%13+1;
        deck[i].suit=i/13;
    }
}

void shuffle_deck(card deck[]){
    int i,j;
    srand(time(NULL));
    for(i=0;i<52;i++){
        j=rand()%52;
        card temp=deck[i];
        deck[i]=deck[j];
        deck[j]=temp;
    }
}

void deal_card(card deck[],int top_card,card hand[]){
    int i;
    for(i=0;i<5;i++){
        hand[i].rank=deck[top_card].rank;
        hand[i].suit=deck[top_card].suit;
        top_card++;
    }
}

int compare_hands(card hand1[],card hand2[]){
