#include <stdio.h>
#include <stdlib.h>

// Define a structure for our data
typedef struct {
    int id;
    char name[50];
} Person;

// Function to compare two Person structs based on their ID
int compare(const void *a, const void *b) {
    const Person *personA = a;
    const Person *personB = b;

    if (personA->id < personB->id) {
        return -1;
    } else if (personA->id > personB->id) {
        return 1;
    } else {
        return 0;
    }
}

// Function to print a Person struct
void printPerson(const void *ptr) {
    const Person *person = ptr;

    printf("%d - %s\n", person->id, person->name);
}

// Function to sort an array of Person structs using qsort
void sortArray(Person arr[], int size) {
    qsort(arr, size, sizeof(Person), compare);
}

int main() {
    // Initialize an array of Person structs
    Person people[] = {
        {1, "Alice"},
        {3, "Bob"},
        {2, "Charlie"},
        {5, "David"},
        {4, "Eve"}
    };

    // Print the unsorted array
    printf("Unsorted array:\n");
    for (int i = 0; i < sizeof(people) / sizeof(Person); i++) {
        printPerson(&people[i]);
    }

    // Sort the array
    sortArray(people, sizeof(people) / sizeof(Person));

    // Print the sorted array
    printf("\nSorted array:\n");
    for (int i = 0; i < sizeof(people) / sizeof(Person); i++) {
        printPerson(&people[i]);
    }

    return 0;
}

