//Falcon-180B DATASET v1.0 Category: Queue Implementation ; Style: realistic
#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 1000

typedef struct {
    int data;
    struct node* next;
} Node;

typedef struct {
    Node* front;
    Node* rear;
    int size;
} Queue;

Queue* createQueue() {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    if(q == NULL) {
        printf("Memory error\n");
        exit(0);
    }
    q->front = q->rear = NULL;
    q->size = 0;
    return q;
}

int isEmpty(Queue* q) {
    return (q->front == NULL && q->rear == NULL);
}

int isFull(Queue* q) {
    return (q->size == MAX_SIZE);
}

void enqueue(Queue* q, int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if(newNode == NULL) {
        printf("Memory error\n");
        exit(0);
    }
    newNode->data = data;
    newNode->next = NULL;
    if(isEmpty(q)) {
        q->front = q->rear = newNode;
    }
    else {
        q->rear->next = newNode;
        q->rear = newNode;
    }
    q->size++;
}

int dequeue(Queue* q) {
    int data;
    Node* temp = q->front;
    if(isEmpty(q)) {
        printf("Queue is empty\n");
        exit(0);
    }
    data = q->front->data;
    q->front = q->front->next;
    q->size--;
    free(temp);
    return data;
}

void display(Queue* q) {
    Node* temp = q->front;
    if(isEmpty(q)) {
        printf("Queue is empty\n");
        exit(0);
    }
    printf("Queue elements are: ");
    while(temp!= NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

int main() {
    Queue* q = createQueue();
    enqueue(q, 10);
    enqueue(q, 20);
    enqueue(q, 30);
    enqueue(q, 40);
    enqueue(q, 50);
    display(q);
    dequeue(q);
    dequeue(q);
    dequeue(q);
    display(q);
    return 0;
}

//Falcon-180B DATASET v1.0 Category: Modern Encryption ; Style: realistic
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define KEY_LENGTH 16
#define BLOCK_SIZE 8
#define ROUNDS 10

void generate_key(char key[KEY_LENGTH]) {
    srand(time(NULL));

    for (int i = 0; i < KEY_LENGTH; i++) {
        key[i] = rand() % 256;
    }
}

void encrypt(char plaintext[BLOCK_SIZE], char key[KEY_LENGTH]) {
    char ciphertext[BLOCK_SIZE] = {0};

    for (int i = 0; i < BLOCK_SIZE; i++) {
        ciphertext[i] = plaintext[i] ^ key[i % KEY_LENGTH];
    }

    for (int round = 0; round < ROUNDS; round++) {
        for (int i = 0; i < BLOCK_SIZE; i++) {
            ciphertext[i] = (ciphertext[i] >> 1) | (ciphertext[i] << 7);
        }
    }

    for (int i = 0; i < BLOCK_SIZE; i++) {
        plaintext[i] = ciphertext[i];
    }
}

void decrypt(char ciphertext[BLOCK_SIZE], char key[KEY_LENGTH]) {
    char plaintext[BLOCK_SIZE] = {0};

    for (int i = 0; i < BLOCK_SIZE; i++) {
        plaintext[i] = ciphertext[i] ^ key[i % KEY_LENGTH];
    }

    for (int round = 0; round < ROUNDS; round++) {
        for (int i = 0; i < BLOCK_SIZE; i++) {
            plaintext[i] = (plaintext[i] >> 1) | (plaintext[i] << 7);
        }
    }

    for (int i = 0; i < BLOCK_SIZE; i++) {
        ciphertext[i] = plaintext[i];
    }
}

int main() {
    char plaintext[BLOCK_SIZE] = "Hello, world!";
    char key[KEY_LENGTH];

    generate_key(key);

    printf("Plaintext: %s\n", plaintext);
    encrypt(plaintext, key);
    printf("Ciphertext: ");
    for (int i = 0; i < BLOCK_SIZE; i++) {
        printf("%02X ", plaintext[i]);
    }
    printf("\n");

    decrypt(plaintext, key);
    printf("Decrypted: %s\n", plaintext);

    return 0;
}

