int word_lengths[NUM_WORDS];

// Function to generate random words
void generate_words() {
    int i;
    for (i = 0; i < NUM_WORDS; i++) {
        words[i] = (char *) malloc(WORD_LENGTH + 1);
        word_lengths[i] = rand() % WORD_LENGTH + 1;
        int j;
        for (j = 0; j < word_lengths[i]; j++) {
            int k = rand() % 26 + 'a';
            words[i][j] = k;
        }
        words[i][word_lengths[i]] = '\0';
    }
