    int i;
    for (i = 0; i < strlen(correct_word); i++) {
        if (typed_word[i]!= correct_word[i]) {
            return 0;
        }
    }
    return 1;
}

// Function to calculate the WPM
double calculate_wpm(int num_words, double time_taken) {
