int min_color[V];
int max_color[V];

void init_graph();
void init_colors();
void print_solution();
void color_graph(int v, int c);

int main() {
    init_graph();
    init_colors();
    int i, j;
    for (i = 0; i < V; i++) {
        color_graph(i, 1);
    }
    print_solution();
    return 0;
}

void init_graph() {
    int i, j;
    for (i = 0; i < V; i++) {
        for (j = 0; j < V; j++) {
            graph[i][j] = 0;
        }
    }
}

void init_colors() {
    int i;
    for (i = 0; i < V; i++) {
        min_color[i] = i + 1;
        max_color[i] = i + 1;
    }
}

