#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <netdb.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <sys/wait.h>

#define PORT 8080

int main() {
    int server_fd, client_fd, bytes_read;
    struct sockaddr_in server_addr, client_addr;
    int server_addrlen, client_addrlen;
    char buffer[1024];
    int size;
    char *proxy_url;

    proxy_url = getenv("http_proxy");
    if (proxy_url == NULL) {
        printf("Error: no http_proxy environment variable set\n");
        exit(1);
    }

    // Create a socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket");
        exit(1);
    }

    // Bind the socket to a port
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addrlen = sizeof(server_addr);

    if (bind(server_fd, (struct sockaddr *)&server_addr, server_addrlen) == -1) {
        perror("bind");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(server_fd, 5) == -1) {
        perror("listen");
        exit(1);
    }

    printf("Listening for incoming connections on port %d...\n", PORT);

    // Accept a client connection
    client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_addrlen);
    if (client_fd == -1) {
        perror("accept");
        exit(1);
    }

    // Connect to the proxy server
    if (connect(client_fd, (struct sockaddr *)&client_addr, client_addrlen) == -1) {
        perror("connect");
        exit(1);
    }

    printf("Connected to the proxy server\n");

    // Forward the request from the client to the server
    size = recv(client_fd, buffer, sizeof(buffer), 0);
    if (size == -1) {
        perror("recv");
        exit(1);
    }
    printf("Request from client: %s\n", buffer);

    if (proxy_url) {
        // Set the proxy environment variable
        setenv("http_proxy", proxy_url, 1);

        // Connect to the server
        if (connect(server_fd, (struct sockaddr *)&server_addr, server_addrlen) == -1) {
            perror("connect");
            exit(1);
        }

        printf("Connected to the server\n");
    } else {
        // Forward the request directly to the server
        if (connect(server_fd, (struct sockaddr *)&server_addr, server_addrlen) == -1) {
            perror("connect");
            exit(1);
        }

        printf("Connected to the server\n");
    }

    // Forward the response from the server to the client
    size = recv(server_fd, buffer, sizeof(buffer), 0);
    if (size == -1) {
        perror("recv");
        exit(1);
    }
    printf("Response from server: %s\n", buffer);

    send(client_fd, buffer, size, 0);

    close(client_fd);
    close(server_fd);

    return 0;
}

