#include <stdio.h>

// Function to solve the knapsack problem using greedy algorithm
int knapsack(int W, int wt[], int val[], int n)
{
    int i, w;
    int val_sum = 0;

    // Create a 2D array to store the cumulative values
    int cumm[n+1][W+1];

    // Initialize the first column of the 2D array
    for (i = 0; i <= n; i++)
        cumm[i][0] = 0;

    // Initialize the first row of the 2D array
    for (i = 1; i <= W; i++)
        cumm[0][i] = 0;

    // Fill the 2D array
    for (i = 1; i <= n; i++)
    {
        for (w = 1; w <= W; w++)
        {
            if (wt[i-1] <= w)
            {
                cumm[i][w] = cumm[i-1][w] + val[i-1];
                if (cumm[i][w] > cumm[i-1][w-wt[i-1]])
                    cumm[i][w] = cumm[i-1][w-wt[i-1]];
            }
            else
            {
                cumm[i][w] = cumm[i-1][w];
            }
        }
    }

    // Return the maximum value that can be obtained
    return cumm[n][W];
}

// Driver code
int main()
{
    int W = 8, n = 4;
    int wt[] = {2, 4, 6, 8};
    int val[] = {3, 5, 8, 9};
    int i;

    printf("Maximum value that can be obtained = %d\n", knapsack(W, wt, val, n));

    return 0;
}

