#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int size;
    int* arr;
} Bucket;

void initialize_bucket(Bucket* bucket, int size) {
    bucket->size = size;
    bucket->arr = (int*) malloc(size * sizeof(int));
    if (bucket->arr == NULL) {
        fprintf(stderr, "Failed to allocate memory for bucket\n");
        exit(1);
    }
}

void free_bucket(Bucket* bucket) {
    free(bucket->arr);
    bucket->arr = NULL;
}

void print_bucket(Bucket* bucket) {
    printf("Bucket:\n");
    for (int i = 0; i < bucket->size; i++) {
        printf("%d ", bucket->arr[i]);
    }
    printf("\n");
}

void sort_bucket(Bucket* bucket, int* arr) {
    int n = bucket->size;
    for (int i = 0; i < n; i++) {
        arr[i] = bucket->arr[i];
    }
}

int main() {
    int n = 5;
    Bucket bucket;
    initialize_bucket(&bucket, n);

    for (int i = 0; i < n; i++) {
        bucket.arr[i] = rand() % 10;
    }

    printf("Before sorting:\n");
    print_bucket(&bucket);

    sort_bucket(&bucket, bucket.arr);

    printf("After sorting:\n");
    print_bucket(&bucket);

    free_bucket(&bucket);

    return 0;
}

