// Nucleotide base pairs
#define A 'A'
#define C 'C'
#define G 'G'
#define T 'T'

// Error probabilities
#define INSERTION_PROB 0.01
#define DELETION_PROB 0.01
#define SUBSTITUTION_PROB 0.01

// Generate a random nucleotide base pair
char get_random_base() {
    // Generate a random number between 0 and 3
    int r = rand() % 4;

    // Return the corresponding base pair
    switch (r) {
        case 0:
            return A;
        case 1:
            return C;
        case 2:
            return G;
        case 3:
            return T;
    }
}

// Insert a random nucleotide base pair into a string
char *insert_base(char *str, int pos) {
    // Create a new string with the inserted base pair
    char *new_str = (char *)malloc(strlen(str) + 2);
    strcpy(new_str, str);
    new_str[pos] = get_random_base();
    new_str[pos + 1] = '\0';

    // Return the new string
    return new_str;
}

// Delete a random nucleotide base pair from a string
char *delete_base(char *str, int pos) {
    // Create a new string with the deleted base pair
    char *new_str = (char *)malloc(strlen(str) - 1);
    strcpy(new_str, str);
    new_str[pos] = '\0';

    // Return the new string
    return new_str;
}

// Substitute a random nucleotide base pair into a string
char *substitute_base(char *str, int pos) {
    // Create a new string with the substituted base pair
    char *new_str = (char *)malloc(strlen(str) + 1);
    strcpy(new_str, str);
    new_str[pos] = get_random_base();

    // Return the new string
    return new_str;
}

// Simulate the sequencing of a DNA strand
char *simulate_sequencing(char *dna_strand) {
    // Create a copy of the DNA strand
    char *sequenced_strand = (char *)malloc(strlen(dna_strand) + 1);
    strcpy(sequenced_strand, dna_strand);

    // Simulate insertion, deletion, and substitution errors
    for (int i = 0; i < strlen(sequenced_strand); i++) {
        // Generate a random number between 0 and 1
        double r = (double)rand() / RAND_MAX;

        // Insert a base pair
        if (r < INSERTION_PROB) {
            sequenced_strand = insert_base(sequenced_strand, i);
        // Delete a base pair
        } else if (r < INSERTION_PROB + DELETION_PROB) {
            sequenced_strand = delete_base(sequenced_strand, i);
        // Substitute a base pair
        } else if (r < INSERTION_PROB + DELETION_PROB + SUBSTITUTION_PROB) {
            sequenced_strand = substitute_base(sequenced_strand, i);
        }
    }

    // Return the sequenced strand
    return sequenced_strand;
}

