// Define the maximum number of items in the inventory
#define MAX_ITEMS 100

// Define the structure of an item in the inventory
typedef struct {
    int id;
    char name[50];
    int quantity;
    float price;
} Item;

// Declare the array of items in the inventory
Item inventory[MAX_ITEMS];

// Declare the number of items in the inventory
int num_items = 0;

// Function to add an item to the inventory
void add_item(Item item) {
    // Check if the inventory is full
    if (num_items == MAX_ITEMS) {
        printf("The inventory is full. Cannot add more items.\n");
        return;
    }

    // Add the item to the inventory
    inventory[num_items] = item;
    num_items++;
}

// Function to remove an item from the inventory
void remove_item(int item_id) {
    // Find the index of the item in the inventory
    int index = -1;
    for (int i = 0; i < num_items; i++) {
        if (inventory[i].id == item_id) {
            index = i;
            break;
        }
    }

    // Check if the item was found
    if (index == -1) {
        printf("Item not found.\n");
        return;
    }

    // Remove the item from the inventory
    for (int i = index; i < num_items - 1; i++) {
        inventory[i] = inventory[i + 1];
    }
    num_items--;
}

// Function to update the quantity of an item in the inventory
void update_quantity(int item_id, int new_quantity) {
    // Find the index of the item in the inventory
    int index = -1;
    for (int i = 0; i < num_items; i++) {
        if (inventory[i].id == item_id) {
            index = i;
            break;
        }
    }

    // Check if the item was found
    if (index == -1) {
        printf("Item not found.\n");
        return;
    }

    // Update the quantity of the item
    inventory[index].quantity = new_quantity;
}

// Function to print the inventory
void print_inventory() {
    printf("Inventory:\n");
    for (int i = 0; i < num_items; i++) {
        printf("%d %s %d %.2f\n", inventory[i].id, inventory[i].name, inventory[i].quantity, inventory[i].price);
