#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Define the structure of a point in 2D space
typedef struct Point {
  double x;
  double y;
} Point;

// Define the structure of a line segment in 2D space
typedef struct LineSegment {
  Point p1;
  Point p2;
} LineSegment;

// Define the structure of a triangle in 2D space
typedef struct Triangle {
  Point p1;
  Point p2;
  Point p3;
} Triangle;

// Function to calculate the distance between two points
double distance(Point p1, Point p2) {
  return sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));
}

// Function to check if a point is on a line segment
int is_on_line_segment(Point p, LineSegment ls) {
  double dx = ls.p2.x - ls.p1.x;
  double dy = ls.p2.y - ls.p1.y;
  double t = ((p.x - ls.p1.x) * dx + (p.y - ls.p1.y) * dy) / (dx * dx + dy * dy);
  return t >= 0 && t <= 1;
}

// Function to check if two line segments intersect
int do_line_segments_intersect(LineSegment ls1, LineSegment ls2) {
  int p1_on_ls2 = is_on_line_segment(ls1.p1, ls2);
  int p2_on_ls2 = is_on_line_segment(ls1.p2, ls2);
  int p3_on_ls1 = is_on_line_segment(ls2.p1, ls1);
  int p4_on_ls1 = is_on_line_segment(ls2.p2, ls1);
  return p1_on_ls2 || p2_on_ls2 || p3_on_ls1 || p4_on_ls1;
}

// Function to check if a point is inside a triangle
int is_point_in_triangle(Point p, Triangle t) {
  double alpha = ((t.p2.y - t.p1.y) * (p.x - t.p1.x) - (t.p2.x - t.p1.x) * (p.y - t.p1.y)) /
                ((t.p2.y - t.p1.y) * (t.p3.x - t.p1.x) - (t.p2.x - t.p1.x) * (t.p3.y - t.p1.y));
  double beta = ((t.p3.y - t.p2.y) * (p.x - t.p2.x) - (t.p3.x - t.p2.x) * (p.y - t.p2.y)) /
               ((t.p3.y - t.p2.y) * (t.p1.x - t.p2.x) - (t.p3.x - t.p2.x) * (t.p1.y - t.p2.y));
  double gamma = 1.0 - alpha - beta;
  return alpha >= 0 && beta >= 0 && gamma >= 0;
}

// Function to print a point
void print_point(Point p) {
  printf("(%f, %f)\n", p.x, p.y);
}

// Function to print a line segment
void print_line_segment(LineSegment ls) {
  printf("Line segment from ");
  print_point(ls.p1);
  printf(" to ");
  print_point(ls.p2);
  printf("\n");
}

// Function to print a triangle
void print_triangle(Triangle t) {
  printf("Triangle with vertices:\n");
  print_point(t.p1);
  print_point(t.p2);
  print_point(t.p3);
  printf("\n");
}

int main() {
  // Define some points, line segments, and triangles
  Point p1 = {0.0, 0.0};
  Point p2 = {1.0, 0.0};
  Point p3 = {0.0, 1.0};
  LineSegment ls1 = {p1, p2};
  LineSegment ls2 = {p2, p3};
  Triangle t = {p1, p2, p3};

  // Print the points, line segments, and triangles
  printf("Points:\n");
  print_point(p1);
  print_point(p2);
  print_point(p3);
  printf("\nLine segments:\n");
  print_line_segment(ls1);
  print_line_segment(ls2);
  printf("\nTriangle:\n");
  print_triangle(t);

  // Check if the line segments intersect
  int do_intersect = do_line_segments_intersect(ls1, ls2);
  if (do_intersect) {
    printf("The line segments intersect.\n");
  } else {
    printf("The line segments do not intersect.\n");
  }

  // Check if the point is inside the triangle
  int is_inside = is_point_in_triangle(p1, t);
  if (is_inside) {
    printf("The point is inside the triangle.\n");
  } else {
    printf("The point is not inside the triangle.\n");
  }

  return 0;
}

