#define MAX_RECORDS 100
#define MAX_FIELD_LENGTH 20

typedef struct {
  char name[MAX_FIELD_LENGTH];
  char address[MAX_FIELD_LENGTH];
  char phone[MAX_FIELD_LENGTH];
} record;

record database[MAX_RECORDS];
int num_records = 0;

void add_record(char *name, char *address, char *phone) {
  if (num_records == MAX_RECORDS) {
    printf("Database is full.\n");
    return;
  }

  strcpy(database[num_records].name, name);
  strcpy(database[num_records].address, address);
  strcpy(database[num_records].phone, phone);
  num_records++;
}

void print_record(int index) {
  if (index < 0 || index >= num_records) {
    printf("Invalid index.\n");
    return;
  }

  printf("Name: %s\n", database[index].name);
  printf("Address: %s\n", database[index].address);
  printf("Phone: %s\n", database[index].phone);
}

void print_all_records() {
  for (int i = 0; i < num_records; i++) {
    print_record(i);
    printf("\n");
  }
}

void delete_record(int index) {
  if (index < 0 || index >= num_records) {
    printf("Invalid index.\n");
    return;
  }

  for (int i = index; i < num_records - 1; i++) {
    database[i] = database[i + 1];
  }

  num_records--;
