#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <portaudio.h>

#define NUM_CHANNELS 2
#define SAMPLE_RATE 44100
#define FRAMES_PER_BUFFER 1024

typedef struct {
  float gain;
  float freq;
  float phase;
} Oscillator;

typedef struct {
  Oscillator oscillators[2];
} Synth;

void init_oscillator(Oscillator *osc, float gain, float freq) {
  osc->gain = gain;
  osc->freq = freq;
  osc->phase = 0.0f;
}

void init_synth(Synth *synth) {
  init_oscillator(&synth->oscillators[0], 0.5f, 261.63f);
  init_oscillator(&synth->oscillators[1], 0.5f, 329.63f);
}

void process_audio(float *buffer, int frames, void *data) {
  Synth *synth = (Synth *)data;

  for (int i = 0; i < frames; i++) {
    float sample = 0.0f;

    for (int j = 0; j < 2; j++) {
      Oscillator *osc = &synth->oscillators[j];
      sample += osc->gain * sinf(osc->phase);
      osc->phase += 2.0f * M_PI * osc->freq / SAMPLE_RATE;
    }

    buffer[i * NUM_CHANNELS + 0] = sample;
    buffer[i * NUM_CHANNELS + 1] = sample;
  }
}

int main() {
  Synth synth;
  init_synth(&synth);

  PaStream *stream;
  PaError err;

  err = Pa_Initialize();
  if (err != paNoError) goto error;

  err = Pa_OpenDefaultStream(&stream, NUM_CHANNELS, paFloat32, SAMPLE_RATE, FRAMES_PER_BUFFER, paClipOff, process_audio, &synth);
  if (err != paNoError) goto error;

  err = Pa_StartStream(stream);
  if (err != paNoError) goto error;

  printf("Press Enter to quit.\n");
  getchar();

  err = Pa_StopStream(stream);
  if (err != paNoError) goto error;

  err = Pa_CloseStream(stream);
  if (err != paNoError) goto error;

  Pa_Terminate();
  return 0;

error:
  Pa_Terminate();
  fprintf(stderr, "Error: %s\n", Pa_GetErrorText(err));
  return err;
}

