// Gravity's pull, measured in meters per second squared (m/s^2)
#define GRAVITY 9.81

// Initial velocity, measured in meters per second (m/s)
#define INITIAL_VELOCITY 10.0

// Angle of launch, measured in degrees
#define LAUNCH_ANGLE 45.0

// Time step, measured in seconds (s)
#define TIME_STEP 0.05

// Projectile's position, measured in meters (m)
typedef struct {
    double x;
    double y;
} Position;

// Projectile's velocity, measured in meters per second (m/s)
typedef struct {
    double vx;
    double vy;
} Velocity;

// Initialize the projectile's position and velocity
void initialize(Position *pos, Velocity *vel) {
    pos->x = 0.0;
    pos->y = 0.0;
    vel->vx = INITIAL_VELOCITY * cos(LAUNCH_ANGLE * M_PI / 180.0);
    vel->vy = INITIAL_VELOCITY * sin(LAUNCH_ANGLE * M_PI / 180.0);
}

// Update the projectile's position and velocity
void update(Position *pos, Velocity *vel) {
    pos->x += vel->vx * TIME_STEP;
    pos->y += vel->vy * TIME_STEP - 0.5 * GRAVITY * TIME_STEP * TIME_STEP;
    vel->vy -= GRAVITY * TIME_STEP;
}

// Simulate the projectile's flight
void simulate(Position *pos, Velocity *vel) {
    while (pos->y >= 0.0) {
        update(pos, vel);
    }
}

