// Define the function to check if two line segments intersect
int do_line_segments_intersect(line_segment l1, line_segment l2) {
    // Check if the two line segments are parallel
    if ((l1.p1.x - l1.p2.x) * (l2.p1.y - l2.p2.y) - (l1.p1.y - l1.p2.y) * (l2.p1.x - l2.p2.x) == 0) {
