#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// The legendary compression algorithm
int compress(char *input, char *output) {
    // Check for empty input
    if (input == NULL || strlen(input) == 0) {
        return 0;
    }

    // Initialize the output buffer
    output[0] = '\0';

    // Initialize the compression variables
    int count = 1;
    char last = input[0];

    // Loop through the input string
    for (int i = 1; i < strlen(input); i++) {
        // Check if the current character is the same as the last character
        if (input[i] == last) {
            // Increment the count
            count++;
        } else {
            // Append the count and the last character to the output buffer
            sprintf(output + strlen(output), "%d%c", count, last);

            // Reset the count and the last character
            count = 1;
            last = input[i];
        }
    }

    // Append the final count and the last character to the output buffer
    sprintf(output + strlen(output), "%d%c", count, last);

    // Return the length of the compressed string
    return strlen(output);
}

int main() {
    // The input string
    char input[] = "AAABBBCCCDDEEEFFGGHHIIJJ";

    // The output buffer
    char output[100];

    // Compress the input string
    int compressed_length = compress(input, output);

    // Print the original and compressed strings
    printf("Original: %s\n", input);
    printf("Compressed: %s\n", output);
    printf("Compression Ratio: %.2f%%\n", (float)compressed_length / strlen(input) * 100);

    // Celebrate the successful compression!
    printf("Compression complete! Hooray for less bytes!\n");

    return 0;
}

