#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <time.h>

// Mind-bending color definitions
#define R3D "\x1b[31;1m"
#define R3N "\x1b[31;0m"
#define G3D "\x1b[32;1m"
#define G3N "\x1b[32;0m"

// Custom ICMP packet structure
struct icmp_packet
{
    uint8_t type;           // Type of ICMP message
    uint8_t code;           // Code of ICMP message
    uint16_t checksum;      // Checksum of ICMP message
    uint16_t identifier;    // Identifier of ICMP message
    uint16_t sequence_num;  // Sequence number of ICMP message
    uint32_t timestamp;     // Timestamp of ICMP message
};

// Create a raw socket for ICMP
int create_raw_socket()
{
    int sockfd;
    if ((sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_ICMP)) == -1)
    {
        perror("socket");
        return -1;
    }

    // Set socket options to allow sending and receiving ICMP packets
    int optval = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_HDRINCL, &optval, sizeof(optval)) == -1)
    {
        perror("setsockopt");
        return -1;
    }

    return sockfd;
}

// Calculate the checksum of an ICMP packet
uint16_t calculate_checksum(uint16_t *data, int len)
{
    uint32_t sum = 0;
    while (len > 1)
    {
        sum += *data++;
        len -= 2;
    }
    if (len == 1)
    {
        sum += *(uint8_t *)data;
    }
    sum = (sum >> 16) + (sum & 0xFFFF);
    sum += (sum >> 16);
    return ~sum;
}

// Send an ICMP echo request packet
int send_echo_request(int sockfd, struct sockaddr_in *addr, int seq_num)
{
    // Create an ICMP echo request packet
    struct icmp_packet packet;
    packet.type = 8;                   // Echo request
    packet.code = 0;                   // Code 0
    packet.checksum = 0;              // Initialize checksum to 0
    packet.identifier = getpid() & 0xFFFF; // Use process ID as identifier
    packet.sequence_num = seq_num;     // Sequence number
    packet.timestamp = time(NULL);     // Timestamp

    // Calculate the checksum of the packet
    packet.checksum = calculate_checksum((uint16_t *)&packet, sizeof(packet));

    // Send the ICMP echo request packet
    int bytes_sent = sendto(sockfd, &packet, sizeof(packet), 0, (struct sockaddr *)addr, sizeof(*addr));
    if (bytes_sent == -1)
    {
        perror("sendto");
        return -1;
    }

    return bytes_sent;
}

// Receive an ICMP echo reply packet
int receive_echo_reply(int sockfd, struct icmp_packet *packet, struct sockaddr_in *addr, socklen_t *addr_len)
{
    // Receive the ICMP echo reply packet
    int bytes_received = recvfrom(sockfd, packet, sizeof(*packet), 0, (struct sockaddr *)addr, addr_len);
    if (bytes_received == -1)
    {
        perror("recvfrom");
        return -1;
    }

    // Verify the checksum of the packet
    uint16_t checksum = calculate_checksum((uint16_t *)packet, bytes_received);
    if (checksum != 0)
    {
        fprintf(stderr, "Invalid checksum\n");
        return -1;
    }

    return bytes_received;
}

// Ping a host
int ping_host(char *hostname, int count)
{
    // Resolve the hostname to an IP address
    struct hostent *host = gethostbyname(hostname);
    if (!host)
    {
        fprintf(stderr, "Unknown host: %s\n", hostname);
        return -1;
    }

    // Create a raw socket for ICMP
    int sockfd = create_raw_socket();
    if (sockfd == -1)
    {
        return -1;
    }

    // Set up the destination address
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr = *(struct in_addr *)host->h_addr;

    // Send ICMP echo request packets and receive replies
    int seq_num = 0;
    int successful_pings = 0;
    while (count-- > 0)
    {
        // Send an ICMP echo request packet
        int bytes_sent = send_echo_request(sockfd, &addr, seq_num++);
        if (bytes_sent == -1)
        {
            fprintf(stderr, "Error sending ICMP echo request packet\n");
            continue;
        }

        // Receive an ICMP echo reply packet
        struct icmp_packet packet;
        socklen_t addr_len = sizeof(addr);
        int bytes_received = receive_echo_reply(sockfd, &packet, &addr, &addr_len);
        if (bytes_received == -1)
        {
            fprintf(stderr, "Error receiving ICMP echo reply packet\n");
            continue;
        }

        // Check the type and code of the packet
        if (packet.type != 0 || packet.code != 0)
        {
            fprintf(stderr, "Invalid ICMP echo reply packet\n");
            continue;
        }

        // Calculate the round-trip time
        long rtt = (time(NULL) - packet.timestamp) * 1000;

        // Print the ping results
        printf(G3D "%s %ld ms\n" R3N, hostname, rtt);
        successful_pings++;
    }

    // Close the socket
    close(sockfd);

    return successful_pings;
}

// Mind-bending usage message
void usage()
{
    printf(R3D "Usage: ping [options] <hostname>\n" R3N);
    printf(G3D "Options:\n" R3N);
    printf(G3D "-c <count>: Number of pings to send (default: 4)\n" R3N);
    printf(G3D "-h: Display this help message\n" R3N);
}

int main(int argc, char **argv)
{
    // Parse command-line arguments
    int opt;
    int count = 4;
    while ((opt = getopt(argc, argv, "c:h")) != -1)
    {
        switch (opt)
        {
        case 'c':
            count = atoi(optarg);
            break;
        case 'h':
            usage();
            exit(0);
            break;
        default:
            usage();
            exit(1);
        }
    }

    // Get the hostname from the command-line arguments
    char *hostname = argv[optind];
    if (!hostname)
    {
        usage();
        exit(1);
    }

    // Ping the host
    int successful_pings = ping_host(hostname, count);
    if (successful_pings == -1)
    {
        fprintf(stderr, "Error pinging host\n");
        exit(1);
    }

    // Print the ping statistics
    printf(G3D "Ping statistics for %s:\n" R3N, hostname);
    printf(G3D "%d packets transmitted, %d packets received, %d%% packet loss\n" R3N, count, successful_pings, (100 - (successful_pings * 100 / count)));

    return 0;
}

