void sanitize_string(char *str)
{
    char *p = str;
    char *q = str;

    // Remove all non-alphanumeric characters
    while (*p)
    {
        if (!isalnum(*p))
        {
            *q = p;
            *q++ = '\0';
        }
        else
        {
            p++;
        }
    }

    // Lowercase all letters
    while (*q)
    {
        *q = tolower(*q);
        q++;
    }

    // Trim leading and trailing whitespace
    while (*str == ' ')
    {
        str++;
    }

    while (*str && *str != '\0')
    {
        str++;
    }

    str--;

    return;
}

