#include <stdio.h>
#include <string.h>

void parse_c_syntax(char *source)
{
    char *current_position = source;
    char previous_character = '\0';

    while (*current_position)
    {
        switch (*current_position)
        {
            case '(':
                printf("Found parenthesis!\n");
                previous_character = '(';
                break;
            case ')':
                if (previous_character == '(')
                {
                    printf("Found matching parenthesis!\n");
                    previous_character = '\0';
                }
                else
                {
                    printf("Error: unmatched parenthesis.\n");
                }
                break;
            case '{':
                printf("Found curly brace!\n");
                previous_character = '{';
                break;
            case '}':
                if (previous_character == '{')
                {
                    printf("Found matching curly brace!\n");
                    previous_character = '\0';
                }
                else
                {
                    printf("Error: unmatched curly brace.\n");
                }
                break;
            default:
                break;
        }

        current_position++;
    }
}

int main()
{
    char source[] = "((a)) {}";

    parse_c_syntax(source);

    return 0;
}

