#define BOARD_SIZE 3
#define EMPTY_SPOT -1

int board[BOARD_SIZE][BOARD_SIZE] = {{EMPTY_SPOT, EMPTY_SPOT, EMPTY_SPOT},
                              {EMPTY_SPOT, EMPTY_SPOT, EMPTY_SPOT},
                              {EMPTY_SPOT, EMPTY_SPOT, EMPTY_SPOT}};

int main()
{
    int player_move, move_available = 1, game_won = 0, current_player = 1;
    char symbol;

    srand(time(NULL));

    // Game loop
    while (move_available && !game_won)
    {
        // Get the player's move
        printf("Enter your move (1-9): ");
        scanf("%d", &player_move);

        // Validate the move
        if (player_move < 1 || player_move > 9 || board[player_move - 1][player_move - 1] != EMPTY_SPOT)
        {
            printf("Invalid move. Please try again.\n");
            continue;
        }

        // Make the move
        board[player_move - 1][player_move - 1] = current_player;

        // Check if the player has won
        game_won = check_win(current_player);

        // If the player has not won, switch to the next player
        if (!game_won)
        {
            current_player = (current_player == 1) ? 2 : 1;
        }
    }

    // Game over
    if (game_won)
    {
        printf("Congratulations! You won!\n");
    }
    else
    {
        printf("It's a draw.\n");
    }

    return 0;
}

int check_win(int player)
{
    // Check rows
    for (int r = 0; r < BOARD_SIZE; r++)
    {
        if (board[r][0] == board[r][1] && board[r][0] == board[r][2] && board[r][0] == player)
        {
            return 1;
        }
    }

    // Check columns
    for (int c = 0; c < BOARD_SIZE; c++)
    {
        if (board[0][c] == board[1][c] && board[0][c] == board[2][c] && board[0][c] == player)
        {
            return 1;
        }
    }

    // Check diagonals
    if (board[0][0] == board[1][1] && board[0][0] == board[2][2] && board[0][0] == player)
    {
        return 1;
    }

    // No win
    return 0;
}

