#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ipc.h>
#include <sys/msg.h>

#define IPC_KEY 1234
#define MSG_SIZE 1024

int main()
{
    int msg_id, size, r, sender_pid, receiver_pid;
    char msg_buffer[MSG_SIZE];

    // Create a message queue
    msg_id = msgget(IPC_KEY, IPC_CREAT);
    if (msg_id == -1)
    {
        perror("Error creating message queue");
        exit(1);
    }

    // Receive a message
    size = msgrcv(msg_id, msg_buffer, MSG_SIZE, 0, sender_pid);
    if (size == -1)
    {
        perror("Error receiving message");
        exit(1);
    }

    // Print the message
    printf("Received message: %s", msg_buffer);

    // Get the sender's PID
    receiver_pid = getpid();
    printf("Sender's PID: %d", sender_pid);

    // Send a reply message
    strcpy(msg_buffer, "Reply from receiver");
    size = msgsnd(msg_id, msg_buffer, MSG_SIZE, sender_pid);
    if (size == -1)
    {
        perror("Error sending message");
        exit(1);
    }

    // Destroy the message queue
    msgctl(msg_id, IPC_RMID, NULL);

    return 0;
}

