    for (i=0; i<r.num_waypoints; i++) {
        print_waypoint(r.waypoints[i]);
        if (i < r.num_waypoints-1)
            printf(" -> ");
    }
    printf("\n");
}

void print_navigator(struct navigator nav) {
    int i;
    for (i=0; i<nav.num_routes; i++) {
        print_route(nav.routes[i]);
    }
}

