struct email {
    char *subject;
    struct email *next;
};

static struct email *email_list = NULL;

size_t email_fetch_callback(void *ptr, size_t size, size_t nmemb, void *data) {
    char *response = (char *)ptr;
    char *subject = strstr(response, "Subject: ");
    if (subject) {
        subject += 9; // Skip "Subject: "
        char *end = strchr(subject, '\n'); // Find end of subject line
        if (end) *end = '\0'; // Null terminate the subject
        struct email *new_email = malloc(sizeof(struct email));
        if (new_email) {
            new_email->subject = strdup(subject);
            new_email->next = email_list;
            email_list = new_email;
        }
    }
    return size * nmemb;
}

