#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#define SNAP_LEN 1518  // Maximum number of bytes to capture

void packet_handler(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    struct ip *ip_header;
    char source_ip[INET_ADDRSTRLEN];
    char dest_ip[INET_ADDRSTRLEN];

    // Get the IP header from the packet
    ip_header = (struct ip *)(packet + 14); // 14 bytes of Ethernet header
    inet_ntop(AF_INET, &(ip_header->ip_src), source_ip, INET_ADDRSTRLEN);
    inet_ntop(AF_INET, &(ip_header->ip_dst), dest_ip, INET_ADDRSTRLEN);

    // Print packet details
    printf("Packet Length: %d\n", header->len);
    printf("Source IP: %s\n", source_ip);
    printf("Destination IP: %s\n", dest_ip);
    printf("---------------------------------------------------\n");
}

int main(int argc, char *argv[]) {
    char *dev; // Device to capture packets
    char errbuf[PCAP_ERRBUF_SIZE]; // Error buffer

    // Get the device name
    dev = pcap_lookupdev(errbuf);
    if (dev == NULL) {
        fprintf(stderr, "Could not find device: %s\n", errbuf);
        return EXIT_FAILURE;
    }
    printf("Using device: %s\n", dev);

    // Open the device for live packet capture
    pcap_t *handle = pcap_open_live(dev, SNAP_LEN, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Could not open device %s: %s\n", dev, errbuf);
        return EXIT_FAILURE;
    }

    // Set a filter to capture only TCP, UDP, and ICMP packets
    struct bpf_program filter;
    char filter_exp[] = "ip"; // Capture only IP packets
    if (pcap_compile(handle, &filter, filter_exp, 0, PCAP_NETMASK_UNKNOWN) == -1) {
        fprintf(stderr, "Could not parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return EXIT_FAILURE;
    }
    if (pcap_setfilter(handle, &filter) == -1) {
        fprintf(stderr, "Could not install filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return EXIT_FAILURE;
    }

    // Start capturing packets
    printf("Starting packet capture. Press Ctrl+C to stop.\n");
    pcap_loop(handle, 0, packet_handler, NULL);

    // Close the handle
    pcap_freecode(&filter);
    pcap_close(handle);
    return EXIT_SUCCESS;
}

