#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define DAYS_IN_WEEK 7
#define MAX_TEMP 35
#define MIN_TEMP -10

// Weather Types
const char *weather_types[] = {
    "Sunny",
    "Cloudy",
    "Rainy",
    "Stormy",
    "Snowy",
    "Foggy"
};

// Structure to hold daily weather information
typedef struct {
    int day;
    int temperature;
    const char *weather;
} Weather;

// Function to generate random weather data
Weather generate_weather(int day) {
    Weather daily_weather;
    daily_weather.day = day;
    daily_weather.temperature = (rand() % (MAX_TEMP - MIN_TEMP + 1)) + MIN_TEMP;
    daily_weather.weather = weather_types[rand() % (sizeof(weather_types) / sizeof(weather_types[0]))];

    return daily_weather;
}

// Function to display the weather forecast
void display_forecast(Weather forecast[DAYS_IN_WEEK]) {
    printf("Weekly Weather Forecast:\n");
    printf("--------------------------\n");
    printf("| Day       | Temp (°C) | Weather  |\n");
    printf("--------------------------\n");

    for (int i = 0; i < DAYS_IN_WEEK; i++) {
        printf("| Day %2d    |   %3d    | %-8s |\n",
               forecast[i].day, 
               forecast[i].temperature, 
               forecast[i].weather);
    }

    printf("--------------------------\n");
}

int main() {
    srand(time(NULL)); // Seed for random number generation
    Weather forecast[DAYS_IN_WEEK];

    // Generate weather for each day of the week
    for (int i = 0; i < DAYS_IN_WEEK; i++) {
        forecast[i] = generate_weather(i + 1); // Days are 1-indexed (1 to 7)
    }

    // Display the weather forecast
    display_forecast(forecast);

    return 0;
}

//LLAMA2-13B DATASET v1.0 Category: String manipulation ; Style: retro
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_LENGTH 100

// Retro-style string manipulation functions

void reverse_string(char* str) {
  int i, j;
  char temp;

  for (i = 0, j = strlen(str) - 1; i < j; i++, j--) {
    temp = str[i];
    str[i] = str[j];
    str[j] = temp;
  }
}

void uppercase_string(char* str) {
  int i;

  for (i = 0; str[i] != '\0'; i++) {
    str[i] = toupper(str[i]);
  }
}

void lowercase_string(char* str) {
  int i;

  for (i = 0; str[i] != '\0'; i++) {
    str[i] = tolower(str[i]);
  }
}

void replace_string(char* str, char old_char, char new_char) {
  int i;

  for (i = 0; str[i] != '\0'; i++) {
    if (str[i] == old_char) {
      str[i] = new_char;
    }
  }
}

int main() {
  char str[] = "Hello, World!";

  // Retro-style string manipulation examples

  reverse_string(str);
  printf("Reversed string: %s\n", str);

  uppercase_string(str);
  printf("Uppercase string: %s\n", str);

  lowercase_string(str);
  printf("Lowercase string: %s\n", str);

  replace_string(str, 'e', 'E');
