#include <stdio.h>
#include <string.h>

void recursive_string_manipulation(char* str) {
  if (*str == '\0') {
    printf("The string is empty\n");
    return;
  }

  char* first_char = str;
  char* rest = str + 1;

  // Case 1: String contains only one character
  if (strcmp(rest, "") == 0) {
    printf("The string contains only one character: %c\n", *first_char);
    return;
  }

  // Case 2: String contains more than one character
  recursive_string_manipulation(rest);

  // Case 3: String starts with a special character
  if (*first_char == '!' || *first_char == '?' || *first_char == '.' || *first_char == ',' || *first_char == '$') {
    printf("The string starts with a special character: %c\n", *first_char);
    return;
  }

  // Case 4: String contains a consecutive sequence of the same character
  int count = 1;
  for (char* p = rest; *p; p++) {
    if (*p == *first_char) {
      count++;
    } else {
      break;
    }
  }
  if (count > 1) {
    printf("The string contains a consecutive sequence of the same character: %c%c%c...\n", *first_char, *first_char, *first_char);
  }

  // Case 5: String contains a palindrome
  char* mid = str + strlen(str) / 2;
  if (strcmp(first_char, mid) == 0 && strcmp(mid, first_char) == 0) {
    printf("The string contains a palindrome: %s\n", str);
  }
}

int main() {
  char str[] = "Hello, world!";
  recursive_string_manipulation(str);
  return 0;
}

