    complex_subtract(a, b, &c);
    printf("a - b = %f + %fi = %f + %fi\n", a.real, a.imag, c.real, c.imag);

    // Example 3: Multiplication
    a.real = 2, a.imag = 3;
    b.real = 4, b.imag = 5;
    c.real = 0, c.imag = 0;
    complex_multiply(a, b, &c);
    printf("a * b = %f + %fi * %f + %fi = %f + %fi\n", a.real, a.imag, b.real, b.imag, c.real, c.imag);

    // Example 4: Division
    a.real = 2, a.imag = 3;
    b.real = 4, b.imag = 5;
    c.real = 1, c.imag = 0;
