#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 25
#define HOST "smtp.gmail.com"

#define MAX_MESSAGE_LENGTH 512
#define MAX_USERNAME_LENGTH 32
#define MAX_PASSWORD_LENGTH 32

struct email {
    char *username;
    char *password;
    char *subject;
    char *message;
};

void send_email(struct email *email) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    inet_pton(AF_INET, HOST, &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connection failed");
        exit(EXIT_FAILURE);
    }

    char *message = email->message;
    int message_len = strlen(message);

    // Split the message into multiple packets if it's too long
    if (message_len > MAX_MESSAGE_LENGTH) {
        char *packet = malloc(MAX_MESSAGE_LENGTH);
        int packet_len = message_len;
        while (packet_len > 0) {
            int len = send(sock, packet, packet_len, 0);
            if (len < 0) {
                perror("sending packet failed");
                exit(EXIT_FAILURE);
            }
            packet_len -= len;
            packet += len;
        }
    } else {
        int len = send(sock, message, message_len, 0);
        if (len < 0) {
            perror("sending message failed");
            exit(EXIT_FAILURE);
        }
    }

    close(sock);
}

int main() {
    struct email email = {
        .username = "your_email@example.com",
        .password = "your_password",
        .subject = "Hello, World!",
        .message = "This is a test email sent from a protected C program."
    };

    send_email(&email);

    return 0;
}

