#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CLIENT_CONNECTIONS 10
#define PORT_RANGE 1024-2048

int main(int argc, char *argv[]) {
  if (argc < 2) {
    printf("Usage: %s <host_ip>\n", argv[0]);
    return 1;
  }

  int sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0) {
    perror("socket() failed");
    return 1;
  }

  struct sockaddr_in server_addr = {
    .sin_family = AF_INET,
    .sin_port = htons(8080),
    .sin_addr.s_addr = inet_addr(argv[1]),
  };

  if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
    perror("connect() failed");
    return 1;
  }

  printf("Connected to %s\n", argv[1]);

  // Scan for open ports on the target host
  for (int i = 0; i < PORT_RANGE; i++) {
    struct sockaddr_in client_addr = {
      .sin_family = AF_INET,
      .sin_port = htons(i + 1),
      .sin_addr.s_addr = server_addr.sin_addr.s_addr,
    };

    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
      perror("socket() failed");
      continue;
    }

    if (connect(sock, (struct sockaddr *)&client_addr, sizeof(client_addr)) < 0) {
      perror("connect() failed");
      close(sock);
      continue;
    }

    char buffer[1024];
    int bytes_read = recv(sock, buffer, 1024, 0);
    if (bytes_read < 0) {
      perror("recv() failed");
      close(sock);
      continue;
    }

    printf("Port %d is open on %s\n", ntohs(client_addr.sin_port), argv[1]);
    close(sock);
  }

  close(sock);
  return 0;
}

