#include <stdio.h>
#include <stdint.h>

// Define a struct to represent a "color"
typedef struct {
    uint8_t red;   // Red component (0-255)
    uint8_t green; // Green component (0-255)
    uint8_t blue;  // Blue component (0-255)
} color_t;

// Function to perform bitwise AND on two colors
color_t and(color_t a, color_t b) {
    return (color_t) {
        .red = a.red & b.red,
        .green = a.green & b.green,
        .blue = a.blue & b.blue
    };
}

// Function to perform bitwise OR on two colors
color_t or(color_t a, color_t b) {
    return (color_t) {
        .red = a.red | b.red,
        .green = a.green | b.green,
        .blue = a.blue | b.blue
    };
}

// Function to perform bitwise XOR on two colors
color_t xor(color_t a, color_t b) {
    return (color_t) {
        .red = a.red ^ b.red,
        .green = a.green ^ b.green,
        .blue = a.blue ^ b.blue
    };
}

// Function to perform bitwise NOT on a color
color_t not(color_t a) {
    return (color_t) {
        .red = ~a.red,
        .green = ~a.green,
        .blue = ~a.blue
    };
}

int main() {
    // Initialize some colors
    color_t c1 = {.red = 0xFF, .green = 0x00, .blue = 0x00};
    color_t c2 = {.red = 0x00, .green = 0xFF, .blue = 0x00};
    color_t c3 = {.red = 0xFF, .green = 0xFF, .blue = 0x00};

    // Perform bitwise operations on the colors
    color_t result1 = and(c1, c2);
    color_t result2 = or(c1, c2);
