    printf("OR: %08x%08x%08x\n", result2.red, result2.green, result2.blue);
    printf("XOR: %08x%08x%08x\n", result3.red, result3.green, result3.blue);
    printf("NOT: %08x%08x%08x\n", result4.red, result4.green, result4.blue);

    return 0;
}

