#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#define MAX_VERTICES 100
#define MIN_COLOR 0
#define MAX_COLOR 6

typedef struct Graph {
    int num_vertices;
    int** adj_matrix;
} Graph;

void create_graph(Graph* graph, int num_vertices) {
    graph->num_vertices = num_vertices;
    graph->adj_matrix = malloc(num_vertices * sizeof(int*));
    for (int i = 0; i < num_vertices; i++) {
        graph->adj_matrix[i] = malloc(num_vertices * sizeof(int));
        for (int j = 0; j < num_vertices; j++) {
            graph->adj_matrix[i][j] = 0;
        }
    }
}

void add_edge(Graph* graph, int src, int dest) {
    graph->adj_matrix[src][dest] = 1;
    graph->adj_matrix[dest][src] = 1;
}

void free_graph(Graph* graph) {
    for (int i = 0; i < graph->num_vertices; i++) {
        free(graph->adj_matrix[i]);
    }
    free(graph->adj_matrix);
}

int** find_neighbors(Graph* graph, int vertex) {
    int** neighbors = malloc(graph->num_vertices * sizeof(int*));
    int count = 0;

    for (int i = 0; i < graph->num_vertices; i++) {
        if (graph->adj_matrix[vertex][i] == 1) {
            neighbors[count] = &graph->adj_matrix[i][0];
            count++;
        }
    }

    return neighbors;
}

bool is_safe_to_color(Graph* graph, int vertex, int color) {
    int** neighbors = find_neighbors(graph, vertex);

    for (int i = 0; i < graph->num_vertices; i++) {
        if (neighbors[i] != NULL && graph->adj_matrix[vertex][*neighbors[i]] == 1 && graph->adj_matrix[*neighbors[i]][vertex] == 1 && graph->adj_matrix[*neighbors[i]][vertex] != color) {
            free(neighbors);
            return false;
        }
    }

    free(neighbors);
    return true;
}

int graph_coloring(Graph* graph) {
    int* coloring = calloc(graph->num_vertices, sizeof(int));

    for (int vertex = 0; vertex < graph->num_vertices; vertex++) {
        int color = MIN_COLOR;

        while (!is_safe_to_color(graph, vertex, color)) {
            color++;
            if (color > MAX_COLOR) {
                free(coloring);
                return -1;
            }
        }

        coloring[vertex] = color;
    }

    free(coloring);
    return 1;
}

int main() {
    Graph graph;
    create_graph(&graph, 7);

    add_edge(&graph, 0, 1);
    add_edge(&graph, 0, 2);
    add_edge(&graph, 1, 3);
    add_edge(&graph, 1, 4);
    add_edge(&graph, 2, 3);
    add_edge(&graph, 2, 5);
    add_edge(&graph, 3, 4);
    add_edge(&graph, 3, 5);
    add_edge(&graph, 4, 5);

    int result = graph_coloring(&graph);

    if (result == -1) {
        printf("Graph cannot be colored with given colors.\n");
    } else {
        printf("Graph colored successfully.\n");
    }

    free_graph(&graph);
    return 0;
}

//MISTRAL-7B DATASET v1.0 Category: Banking Record System ; Style: retro
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 100
#define MAX_NAME_LENGTH 30
#define MAX_ACCOUNT_NUMBER_LENGTH 15

typedef struct {
    char name[MAX_NAME_LENGTH];
    char accountNumber[MAX_ACCOUNT_NUMBER_LENGTH];
    float balance;
} Record;

Record records[MAX_RECORDS];
int numRecords = 0;

void addRecord() {
    if (numRecords >= MAX_RECORDS) {
        printf("Record limit exceeded!\n");
        return;
    }

    printf("Enter name: ");
    scanf("%s", records[numRecords].name);
    printf("Enter account number: ");
    scanf("%s", records[numRecords].accountNumber);
    printf("Enter balance: ");
    scanf("%f", &records[numRecords].balance);

    numRecords++;
}

void displayRecords() {
    printf("\nCurrent records:\n");

    for (int i = 0; i < numRecords; i++) {
        printf("\nName: %s", records[i].name);
        printf("\nAccount Number: %s", records[i].accountNumber);
        printf("\nBalance: %.2f", records[i].balance);
    }
}

void searchRecord() {
    char accountNumber[MAX_ACCOUNT_NUMBER_LENGTH];
    int found = 0;

    printf("Enter account number to search: ");
    scanf("%s", accountNumber);

    for (int i = 0; i < numRecords; i++) {
        if (strcmp(records[i].accountNumber, accountNumber) == 0) {
            printf("\nName: %s", records[i].name);
            printf("\nBalance: %.2f", records[i].balance);
            found = 1;
            break;
        }
    }

    if (!found) {
        printf("\nAccount not found.\n");
    }
}

int main() {
    int choice;

    while (1) {
        printf("\n1. Add Record\n2. Display Records\n3. Search Record\n4. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                addRecord();
                break;
            case 2:
                displayRecords();
                break;
            case 3:
                searchRecord();
                break;
            case 4:
                exit(0);
                break;
            default:
                printf("Invalid choice.\n");
        }
    }

    return 0;
}
